-- SINH TỰ ĐỘNG từ src/lib/content — không sửa tay. Sửa nội dung trong file nguồn rồi sinh lại.
-- Nạp bài tập Lớp 5, Học kì 1 (Toán, Tiếng Việt: Kết nối tri thức; Tiếng Anh: Global Success) — câu soạn sẵn của từng bài.
-- Yêu cầu: đã chạy migration 0001 → 0008, đã có ít nhất 1 tài khoản system_admin và ĐÃ NẠP supabase/seed/curriculum_grade5.sql.
-- Bài đã nạp từ lần trước (cùng seed_id) được bỏ qua, chỉ thêm bài mới.

-- Bài 1 · Bài 1. Ôn tập số tự nhiên (8 câu)
do $$
declare v_admin uuid; v_lesson uuid; v_q uuid;
begin
  select user_id into v_admin from public.user_roles where role = 'system_admin' order by created_at limit 1;
  if v_admin is null then raise exception 'Cần có ít nhất 1 tài khoản system_admin trước khi nạp bài tập'; end if;
  if exists (select 1 from public.lessons where content ->> 'seed_id' = 'toan5-kntt-b01') then return; end if;
  select s.id, 'Bài 1. Ôn tập số tự nhiên', '{"seed_id":"toan5-kntt-b01","kind":"book","book":"Kết nối tri thức","ref":"Bài 1","unit_code":"KNTT.T5.CD1","unit_title":"Chủ đề 1. Ôn tập và bổ sung","description":"Đọc, viết, so sánh số tự nhiên; giá trị của chữ số."}'::jsonb, 'review', v_admin, 'Kết nối tri thức', 1, 1, (select id from public.curriculum_topics where code = 'T5.SO')
  from public.subjects s where s.code = 'toan-5' returning id into v_lesson;
end $$;

