-- Kiểm tra sau khi nạp: mọi đáp án phải đúng định dạng (kết quả mong đợi: 0)
select count(*) as dap_an_sai_dinh_dang from public.questions qq join public.question_keys k on k.question_id = qq.id join public.lessons l on l.id = qq.lesson_id where l.content ? 'seed_id' and not public.answer_key_is_valid(qq.question_type, k.answer_key);
