  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Con diều của Bống\":\nChiều hè, gió nam thổi lồng lộng trên con đê làng. Bống cùng ông nội mang chiếc diều giấy ra bãi cỏ. Ông giữ dây, Bống chạy thật nhanh rồi buông tay. Chiếc diều chao đi chao lại mấy vòng, rồi bỗng vút lên cao. Tiếng sáo diều vi vu, trầm bổng như ai đang thổi khúc nhạc giữa trời. Bống ngửa mặt nhìn theo, thấy mình như cũng đang bay cùng cánh diều. Ông bảo: \"Diều bay được là nhờ gió, còn cháu lớn lên được là nhờ biết bao người thương yêu.\"\n\nBống cùng ai đi thả diều?"}'::jsonb, '["ông nội","bố","các bạn"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V5.DOC.01')) returning id into v_q;
