  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Bến sông ngày ấy\":\nBố tôi lớn lên bên một bến sông nhỏ. Bố kể, ngày ấy bến sông là cả một thế giới của bọn trẻ. Sáng sáng, chúng tắm sông, bơi thi xem ai sang bờ bên kia trước. Chiều chiều, chúng ngồi trên bậc đá, câu những chú cá bống nhỏ xíu. Mùa nước lên, cả bọn rủ nhau thả những chiếc thuyền lá trôi theo dòng. Bây giờ bến sông đã có cây cầu bê tông, nhưng mỗi lần về quê, bố vẫn dắt tôi ra đó. Bố bảo: \"Chỗ này giữ giùm bố cả một thời thơ ấu.\"\n\nBố của \"tôi\" lớn lên ở đâu?"}'::jsonb, '["bên một bến sông nhỏ","ở thành phố","trên núi"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V5.DOC.01')) returning id into v_q;
