  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Cậu thủ môn nhỏ\":\nĐội bóng lớp 5C có một thủ môn nhỏ nhất đội tên là Bin. Lúc đầu, nhiều bạn lo Bin không bắt được những cú sút mạnh. Bin không buồn. Cậu tập bật nhảy mỗi sáng, nhờ anh trai sút bóng cho mình bắt. Trận chung kết, đội bạn được hưởng quả phạt đền. Cả sân im phăng phắc. Bin lao người sang trái, ôm gọn quả bóng trong tay. Các bạn ùa vào công kênh cậu. Bin cười: \"Tớ không cao, nhưng tớ có cả đội ở phía sau.\"\n\nBin đã làm gì để khắc phục chiều cao?"}'::jsonb, '["tập bật nhảy mỗi sáng, nhờ anh trai sút bóng để bắt","bỏ không thi đấu","đổi sang đội khác"]'::jsonb, null, 2, 50, 3, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V5.DOC.01')) returning id into v_q;
