  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Bộ sưu tập nắp chai\":\nChi có một bộ sưu tập rất lạ: hơn hai trăm chiếc nắp chai đủ màu. Mỗi chiếc nắp đều có câu chuyện riêng. Chiếc nắp xanh nhặt được trong chuyến đi biển. Chiếc nắp đỏ là của chai nước cam mẹ mua hôm Chi được giải vẽ tranh. Chi dùng chúng ghép thành bức tranh con cá voi treo ở lớp. Cô giáo khen bức tranh vừa đẹp vừa nhắc mọi người giữ gìn môi trường. Từ đó, cả lớp cùng góp nắp chai cho Chi.\n\nBộ sưu tập của Chi gồm những gì?"}'::jsonb, '["nắp chai đủ màu","tem thư","vỏ ốc"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V5.DOC.01')) returning id into v_q;
