  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Buổi sáng trên rừng thông\":\nMặt trời vừa nhô lên, rừng thông còn chìm trong làn sương mỏng. Từng giọt sương long lanh đọng trên đầu lá kim. Gió thoảng qua, cả rừng thông khẽ reo lên như sóng biển xa. Một chú sóc nâu nhanh nhẹn chuyền từ cành này sang cành khác. Dưới gốc cây, những cây nấm nhỏ xinh xắn đội chiếc mũ màu nâu đỏ. Hít một hơi thật sâu, tôi nghe mùi nhựa thông thơm dịu lan khắp lồng ngực.\n\nKhi mặt trời vừa nhô lên, rừng thông thế nào?"}'::jsonb, '["còn chìm trong làn sương mỏng","nắng chói chang","mưa tầm tã"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V5.DOC.01')) returning id into v_q;
