  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Chuyến thám hiểm hang động\":\nĐoàn học sinh theo chân chú hướng dẫn viên vào một hang động lớn. Lối vào hẹp, nhưng càng đi sâu, lòng hang càng rộng mênh mông. Những khối thạch nhũ khổng lồ rủ xuống như những chiếc rèm đá. Ánh đèn pin rọi vào, thạch nhũ lấp lánh như dát bạc. Chú hướng dẫn viên kể, phải mất hàng triệu năm nước mới tạo nên những hình thù kì lạ ấy. Ai cũng trầm trồ trước bàn tay kì diệu của thiên nhiên.\n\nLòng hang thế nào khi càng đi sâu?"}'::jsonb, '["càng rộng mênh mông","càng hẹp","càng tối và nhỏ"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V5.DOC.01')) returning id into v_q;
