  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Ngọn núi lửa ngủ say\":\nỞ một hòn đảo xa có ngọn núi lửa đã ngủ hàng trăm năm. Trên miệng núi, nước mưa đọng lại thành một hồ nước trong xanh. Dưới chân núi, đất đỏ màu mỡ, người dân trồng cà phê, hồ tiêu xanh tốt. Các nhà khoa học vẫn đặt máy theo dõi ngọn núi suốt ngày đêm. Họ nói núi lửa có thể \"thức giấc\" bất cứ lúc nào, nên con người phải luôn cẩn trọng, vừa biết tận dụng vừa biết tôn trọng thiên nhiên.\n\nTrên miệng núi lửa có gì?"}'::jsonb, '["một hồ nước trong xanh","một ngôi làng","một khu rừng"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V5.DOC.01')) returning id into v_q;
