  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Sa mạc về đêm\":\nBan ngày, sa mạc nóng như lò lửa, cát bỏng rát dưới chân. Nhưng khi mặt trời lặn, không khí lạnh đi rất nhanh. Bầu trời sa mạc về đêm trong vắt, hàng nghìn vì sao lấp lánh như ai rắc kim cương. Đoàn lạc đà nằm nghỉ, đầu gối lên những đụn cát mềm. Người dẫn đường đốt lửa, kể chuyện về những ốc đảo xanh mát giữa biển cát mênh mông. Ai cũng thấy sa mạc không chỉ khắc nghiệt mà còn đẹp lạ lùng.\n\nBan ngày, sa mạc thế nào?"}'::jsonb, '["nóng như lò lửa","lạnh giá","mưa nhiều"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V5.DOC.01')) returning id into v_q;
