  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Cây gạo đầu làng\":\nĐầu làng tôi có một cây gạo già. Mùa xuân, cây gạo nở hoa đỏ rực như ngàn ngọn đuốc thắp sáng cả một góc trời. Đàn chim sáo, chim chào mào kéo về ríu rít. Chúng hót vang như mở hội. Cuối xuân, hoa gạo rụng đầy mặt đất, bọn trẻ nhặt hoa xâu thành vòng. Đến mùa hè, quả gạo chín, bông trắng bay lả tả như tuyết. Với chúng tôi, cây gạo là người bạn già hiền lành của cả làng.\n\nCây gạo nở hoa vào mùa nào?"}'::jsonb, '["mùa xuân","mùa thu","mùa đông"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V5.DOC.01')) returning id into v_q;
