  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Ngọn đèn dầu của ông\":\nÔng nội em kể, ngày nhỏ nhà ông nghèo, không có điện. Tối nào ông cũng thắp ngọn đèn dầu nhỏ để học bài. Không có tiền mua sách, ông mượn sách của bạn rồi chép lại từng trang. Có hôm ông đọc sách đến khuya, khói đèn ám đen cả đầu mũi. Nhờ tự học chăm chỉ, ông trở thành thầy giáo dạy Toán của trường huyện. Ông vẫn giữ ngọn đèn dầu ấy, đặt trên giá sách để nhắc con cháu: học tập là con đường mở ra tương lai.\n\nNgày nhỏ, ông học bài dưới ánh sáng gì?"}'::jsonb, '["ngọn đèn dầu","đèn điện","ánh trăng"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V5.DOC.01')) returning id into v_q;
