  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Cây đàn bầu của Tuấn\":\nTuấn mê tiếng đàn bầu từ khi nghe ông ngoại đánh bài \"Quê hương\". Ông dạy Tuấn cách đặt tay, cách rung dây. Những ngày đầu, ngón tay Tuấn đau rát, tiếng đàn lúc trầm lúc rè. Có lúc Tuấn muốn bỏ cuộc. Ông bảo: \"Đàn bầu chỉ có một dây, nhưng người chơi phải kiên nhẫn gấp trăm lần.\" Tuấn lại cặm cụi tập mỗi tối. Ba năm sau, tiếng đàn của Tuấn vang lên trong hội diễn của tỉnh, ngân nga, tha thiết như lời ru.\n\nAi dạy Tuấn đánh đàn bầu?"}'::jsonb, '["ông ngoại","cô giáo","bố"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V5.DOC.01')) returning id into v_q;
