  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Chiếc tủ sách của lớp\":\nĐầu năm học, lớp 5A lập \"Tủ sách bạn bè\" ở cuối lớp. Mỗi bạn góp hai cuốn sách mình yêu thích. Tủ sách có đủ loại:\n– truyện cổ tích;\n– sách khoa học;\n– truyện tranh về lịch sử.\nGiờ ra chơi, góc lớp lúc nào cũng đông. Minh – người lớp trưởng ít nói – lại là người mượn sách nhiều nhất. Cuối học kì, cả lớp bình chọn cuốn sách hay nhất và viết cảm nghĩ treo cạnh tủ sách.\n\nLớp 5A lập tủ sách ở đâu?"}'::jsonb, '["ở cuối lớp","ở thư viện","ở sân trường"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V5.DOC.01')) returning id into v_q;
