  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Gia đình mê học\":\nNhà bạn Khôi có một thói quen đặc biệt: mỗi tối, cả nhà tắt ti vi một giờ để cùng đọc sách. Bố đọc báo, mẹ đọc sách nấu ăn, còn Khôi và em gái đọc truyện. Đọc xong, mỗi người kể lại cho cả nhà nghe một điều mới. Có hôm, em gái Khôi hỏi:\n– Vì sao cá không bị chết đuối hả anh?\nCả nhà cùng tra sách để tìm câu trả lời. Khôi bảo, nhờ \"giờ đọc sách\", nhà bạn lúc nào cũng rộn tiếng cười và câu hỏi.\n\nMỗi tối, nhà Khôi tắt ti vi bao lâu để đọc sách?"}'::jsonb, '["một giờ","hai giờ","nửa giờ"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V5.DOC.01')) returning id into v_q;
