  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Bức tranh của em\":\nEm vẽ một bức tranh về quê ngoại. Em vẽ dòng sông xanh uốn quanh làng. Em vẽ cánh đồng lúa vàng óng dưới nắng. Em vẽ cả bà ngoại đứng bên ngõ, tay vẫy chào. Thầy dạy mĩ thuật bảo bức tranh còn vụng về nét vẽ, nhưng chứa nhiều tình cảm. Thầy treo bức tranh lên bảng tin của trường. Nhìn bức tranh, em như nghe thấy tiếng gió đồng, như ngửi thấy mùi rơm rạ của quê ngoại.\n\nEm vẽ bức tranh về đâu?"}'::jsonb, '["quê ngoại","thành phố","trường học"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V5.DOC.01')) returning id into v_q;
