  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Những người làm tranh giấy dó\":\nỞ làng nghề ven sông, người ta vẫn làm giấy dó theo cách của ông cha. Vỏ cây dó được ngâm, giã nhuyễn rồi xeo thành từng tờ giấy mỏng. Trên nền giấy xốp, mịn ấy, các nghệ nhân in những bức tranh dân gian: đàn gà, đàn lợn, cảnh đánh vật, cảnh chăn trâu thổi sáo. Màu đỏ lấy từ sỏi son, màu đen lấy từ than lá tre. Mỗi bức tranh như một lời kể về cuộc sống bình dị, vui tươi của làng quê.\n\nGiấy dó được làm từ gì?"}'::jsonb, '["vỏ cây dó","lá chuối","rơm rạ"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V5.DOC.01')) returning id into v_q;
