  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Xưởng phim nhỏ của lớp\":\nLớp 5B quyết định tự làm một bộ phim hoạt hình ngắn. Các bạn nặn những nhân vật bằng đất sét và dựng cảnh bằng bìa giấy. Mỗi cử động nhỏ, các bạn lại chụp một bức ảnh. Phải chụp hơn ba trăm bức ảnh thì nhân vật chú rùa mới đi được một quãng ngắn. Công việc vất vả nhưng ai cũng háo hức. Ngày chiếu phim, cả trường vỗ tay khi chú rùa đất sét về đích trước thỏ.\n\nCác bạn nặn nhân vật bằng gì?"}'::jsonb, '["đất sét","gỗ","nhựa"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V5.DOC.01')) returning id into v_q;
