  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Buổi diễn rối nước\":\nChiều chủ nhật, bố đưa em đi xem múa rối nước. Sân khấu là một mặt ao, phía sau có mái đình nhỏ che rèm tre. Tiếng trống, tiếng sáo vừa nổi lên thì những con rối gỗ lướt ra trên mặt nước. Chú Tễu cười toe toét, giới thiệu từng tiết mục. Có cảnh nông dân cấy lúa, có cảnh đua thuyền và cả cảnh rồng phun nước. Em thắc mắc vì sao con rối cử động được. Bố giải thích rằng các nghệ nhân đứng sau rèm, ngâm mình dưới nước để điều khiển.\n\nSân khấu múa rối nước là gì?"}'::jsonb, '["một mặt ao","một sân khấu gỗ","một bãi cỏ"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V5.DOC.01')) returning id into v_q;
