  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Lá thư gửi bạn nhỏ vùng cao\":\nHoa thân mến!\nMình là Mai, học lớp 5A ở thành phố. Lớp mình vừa quyên góp được ba thùng sách và áo ấm gửi lên trường bạn. Mình gửi kèm cuốn truyện mình thích nhất – cuốn \"Những tấm lòng cao cả\". Mình mong bạn đọc và kể cho mình nghe cảm nghĩ nhé. Mình nghe cô giáo kể ở bản bạn có thác nước đẹp, có ruộng bậc thang vàng óng. Hè này, mình mong được lên thăm bạn.\nThân mến,\nMai\n\nMai học ở đâu?"}'::jsonb, '["ở thành phố","ở vùng cao","ở nông thôn"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V5.DOC.01')) returning id into v_q;
